<template><section class="social-page settings-page"><header class="utility-header"><button @click="router.back()" aria-label="뒤로">‹</button><h1>설정</h1></header><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><template v-if="data"><section class="settings-group"><h2>내 활동</h2><label class="setting-row"><div><strong>휴식 모드</strong><small>신규 추천을 멈추고 기존 대화는 유지해요.</small></div><input type="checkbox" :checked="data.resting" :disabled="busy" @change="rest($event)"/></label><button class="setting-link" @click="loadBlocks">차단 목록·차단 해제 <span>›</span></button><RouterLink class="setting-link" to="/profile/photos">사진 관리 <span>›</span></RouterLink><p v-if="data.reviewStatus!=='NONE'&&data.reviewStatus" class="review-info">{{data.reviewStatus==='PENDING'?'프로필 변경 심사 중':'프로필 보완 요청'}}<br/>{{data.reviewNote}}</p></section><section class="settings-group"><h2>알림</h2><RouterLink class="setting-link" to="/notifications">알림함·이 기기 푸시 설정 <span>›</span></RouterLink><form @submit.prevent="saveNotifications"><label v-for="[key,label] in categories" class="setting-row" :key="key"><span>{{label}}</span><input type="checkbox" v-model="data.notifications[key]" :disabled="busy"/></label><label class="setting-row"><span>야간 방해금지</span><input type="checkbox" v-model="data.notifications.quietHours" :disabled="busy"/></label><div v-if="data.notifications.quietHours" class="quiet-times"><label>시작<select v-model.number="data.notifications.quietStart"><option v-for="h in 24" :value="h-1">{{h-1}}시</option></select></label><span>~</span><label>종료<select v-model.number="data.notifications.quietEnd"><option v-for="h in 24" :value="h-1">{{h-1}}시</option></select></label></div><p class="muted">한국 시간 기준입니다. 꺼 둔 알림도 알림함에는 보관되며, 방해금지 시간의 푸시는 보내지 않습니다.</p><button class="primary" :disabled="busy">알림 설정 저장</button></form></section><section class="settings-group"><h2>계정 관리</h2><button v-if="data.provider==='LOCAL'" class="setting-link" @click="open('password')">비밀번호 변경 <span>›</span></button><button class="setting-link" @click="open('logout')">모든 기기에서 로그아웃 <span>›</span></button><button class="setting-link" @click="open('consents')">약관 동의 이력 <span>›</span></button><button class="setting-link danger" @click="open('withdraw')">회원 탈퇴 <span>›</span></button></section></template><p v-else-if="!error">불러오는 중…</p>
<dialog v-if="data" ref="modal" class="social-dialog" @cancel="busy&&$event.preventDefault()"><header><h2>{{titles[mode]}}</h2><button :disabled="busy" @click="modal.close()" aria-label="닫기">×</button></header><template v-if="mode==='blocks'"><p v-if="!blocks.length">차단한 회원이 없어요.</p><article v-for="p in blocks" :key="p.id" class="blocked-row"><img v-if="p.imageUrl" :src="photo(p.imageUrl)" alt="차단한 회원"/><strong>{{p.nickname}}</strong><button :disabled="busy" @click="unblock(p)">해제</button></article><p class="muted">내 차단만 해제됩니다. 상대의 차단·신고나 매칭 해제는 유지됩니다.</p></template><template v-else-if="mode==='consents'"><p v-if="!data.consents.length">이전 가입 계정으로 별도 저장된 동의 이력이 없습니다.</p><p v-for="c in data.consents" :key="c.id">{{c.version}} · {{new Date(c.acceptedAt).toLocaleString('ko-KR')}}<br/>이용약관·개인정보·성인 확인 동의 / 마케팅 {{c.marketing?'동의':'미동의'}}</p></template><form v-else @submit.prevent="execute"><template v-if="mode==='password'"><label>현재 비밀번호<input type="password" v-model="currentPassword" autocomplete="current-password" required/></label><label>새 비밀번호<input type="password" v-model="newPassword" autocomplete="new-password" minlength="8" maxlength="72" required/></label><label>새 비밀번호 확인<input type="password" v-model="repeatPassword" autocomplete="new-password" required/></label><p>변경 후 모든 기기에서 로그아웃됩니다.</p></template><p v-else-if="mode==='logout'">현재 기기를 포함해 모든 로그인 세션을 종료합니다.</p><template v-else><p>탈퇴하면 로그인과 프로필 공개가 즉시 중단되고 기존 대화에 참여할 수 없습니다. 남은 크레딧도 사용할 수 없습니다.</p><p>현재 테스트 서비스에서는 계정이 비활성화되고 DB 기록은 즉시 전체 삭제되지 않습니다. 기록 삭제는 고객센터로 요청해 주세요.</p><label v-if="data.provider==='LOCAL'">현재 비밀번호<input type="password" v-model="currentPassword" autocomplete="current-password" required/></label><label>확인을 위해 ‘회원탈퇴’ 입력<input v-model="confirmation" required/></label></template><button class="primary" :disabled="busy">{{busy?'처리 중…':mode==='withdraw'?'탈퇴하기':mode==='password'?'비밀번호 변경':'모두 로그아웃'}}</button></form><p v-if="modalError" role="alert">{{modalError}}</p></dialog></section></template>
<script setup>import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import api from '../../api/api';import {clearToken} from '../../utils/auth';import '../../components/social.css';const router=useRouter(),data=ref(),error=ref(''),message=ref(''),busy=ref(false),modal=ref(),mode=ref(''),blocks=ref([]),modalError=ref(''),currentPassword=ref(''),newPassword=ref(''),repeatPassword=ref(''),confirmation=ref('');const categories=[['messages','새 메시지'],['likes','받은 좋아요'],['matches','새 매칭'],['recommendations','오늘의 인연'],['service','심사·신고·문의·크레딧 안내']];const titles={blocks:'차단 목록',password:'비밀번호 변경',logout:'모든 기기 로그아웃',withdraw:'회원 탈퇴',consents:'약관 동의 이력'};const photo=p=>new URL(p,api.defaults.baseURL).href;
onMounted(async()=>{try{data.value=(await api.get('/account/settings')).data;}catch{error.value='설정을 불러오지 못했어요.';}});
async function rest(e){busy.value=true;error.value='';try{data.value=(await api.put('/account/rest',{resting:e.target.checked})).data;message.value=data.value.resting?'휴식 모드를 켰어요.':'휴식 모드를 해제했어요.';}catch{e.target.checked=data.value.resting;error.value='휴식 모드를 변경하지 못했어요.';}finally{busy.value=false;}}
async function saveNotifications(){busy.value=true;error.value='';try{data.value=(await api.put('/account/notifications',data.value.notifications)).data;message.value='알림 설정을 저장했어요.';}catch(e){error.value=e.response?.data?.message||'저장하지 못했어요.';}finally{busy.value=false;}}
function open(value){mode.value=value;modalError.value='';currentPassword.value=newPassword.value=repeatPassword.value=confirmation.value='';modal.value.showModal();}
async function loadBlocks(){try{blocks.value=(await api.get('/social/blocks')).data;open('blocks');}catch{error.value='차단 목록을 불러오지 못했어요.';}}
async function unblock(p){busy.value=true;try{await api.delete(`/social/blocks/${p.id}`);blocks.value=blocks.value.filter(x=>x.id!==p.id);}catch{modalError.value='차단을 해제하지 못했어요.';}finally{busy.value=false;}}
async function execute(){if(busy.value)return;modalError.value='';if(mode.value==='password'&&newPassword.value!==repeatPassword.value){modalError.value='새 비밀번호가 일치하지 않습니다.';return;}busy.value=true;try{if(mode.value==='password')await api.post('/account/password',{currentPassword:currentPassword.value,newPassword:newPassword.value});else if(mode.value==='withdraw')await api.post('/account/withdraw',{password:currentPassword.value,confirmation:confirmation.value});else await api.post('/account/logout-all');clearToken();router.replace('/');}catch(e){modalError.value=e.response?.data?.message||'처리하지 못했어요.';}finally{busy.value=false;}}
</script><style scoped>.settings-page{background:#fff;min-height:100vh}.settings-group{padding:16px 0 26px;border-bottom:8px solid #f7f5f3}.settings-group h2{font-size:13px;color:#a88774;margin-bottom:12px}.setting-row{display:flex;align-items:center;justify-content:space-between;padding:16px 0;font-size:14px;gap:15px}.setting-row strong{font-size:14px}.setting-row small{display:block;font-size:11px;color:#978980;margin-top:6px;line-height:1.6}.setting-row input{width:20px;height:20px;accent-color:#d56f4e;flex:none}.settings-page .setting-link{display:flex;align-items:center;justify-content:space-between;width:100%;padding:17px 0;border:0;border-radius:0;background:none;color:#40332b;font-size:14px;text-decoration:none;text-align:left}.setting-link span{color:#b79c8a}.settings-page .danger{color:#b2493c}.quiet-times{display:flex;gap:12px;align-items:center}.quiet-times label{display:grid;gap:6px;font-size:12px}.quiet-times select{padding:10px;border:1px solid #eee;border-radius:10px;background:white}.blocked-row{display:flex;align-items:center;gap:10px;margin:18px 0}.blocked-row img{width:42px;height:42px;object-fit:cover;border-radius:50%}.blocked-row strong{flex:1;font-size:13px}.social-dialog input{padding:12px;border:1px solid #eaded5;border-radius:10px;font:inherit;min-width:0}.review-info{padding:12px;border-radius:12px;background:#fff4e9;font-size:12px;line-height:1.7}</style>